package com.nse.dashboard.controller;import com.nse.dashboard.model.*;import com.nse.dashboard.service.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.util.*;@RestController @RequestMapping("/api/dashboard") public class DashboardController { @Autowired private CsvParserService parser; @Autowired private DashboardService service; @PostMapping("/analyze") public DashboardResponse analyze(@RequestParam("optionFile") MultipartFile optionFile,@RequestParam("participantFile") MultipartFile participantFile) throws Exception { List<OptionData> optionData=parser.parseOptionCsv(optionFile); List<ParticipantData> participantData=parser.parseParticipantCsv(participantFile); return service.generate(optionData,participantData);}}